WITH with_windows AS (SELECT id, device, browser, started_at, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('MONTH', started_at) ORDER BY started_at DESC, id) AS seq_no, FIRST_VALUE(country, TRUE) OVER (PARTITION BY country, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS row_seq, FIRST_VALUE(browser, TRUE) OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions WHERE device IN ('tablet', 'desktop', 'mobile')) SELECT id, browser, started_at, seq_no, first_known_country, row_seq, first_known_browser FROM with_windows
